 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            r0, r1 = min(x[0] for x in cells), max(x[0] for x in cells)
            c0, c1 = min(x[1] for x in cells), max(x[1] for x in cells)
            # Fill the hollow of the 5-outline with color 2.
            for rr in range(r0, r1 + 1):
                for cc in range(c0, c1 + 1):
                    if grid[rr][cc] == 0:
                        out[rr][cc] = 2
            # The opening at the top emits a leftward ray on the row above.
            if r0 > 0:
                missing = [cc for cc in range(c0, c1 + 1) if grid[r0][cc] == 0]
                if missing:
                    gap = max(missing)
                    for cc in range(gap + 1):
                        out[r0 - 1][cc] = 2
    return out
